local locale = GetLocale()
if locale ~= "itIT" then return end
local _, NS = ...
NS.Tactics = NS.Tactics or {}
local T = NS.Tactics
T[1] = { { "Maledizioni e malattie", "Qualcosa per rimuovere una maledizione o curare una malattia aiuta parecchio. Per il resto è un combattimento facile: ripulisci la sala prima di ingaggiarlo." } }
T[2] = { { "L'evocatore", "Uccidi prima l'evocatore: fa arrivare rinforzi. Poi l'elementale." }, { "Fuoco ovunque", "Danni ad area sul gruppo, peggiori quando il gruppo combatte molto in mischia." } }
T[3] = { { "Scagliato attraverso la sala", "Scaglia i giocatori per la sala. Ripulisci i gruppi più vicini e tienilo con il difensore vicino al tunnel, così nessuno atterra in un altro gruppo." } }
T[4] = { { "Paura quando si indebolisce", "Quando la sua salute cala, terrorizza tutto il gruppo. Prevedi di che spezzarla, oppure ripulisci prima la sala così nessuno corre addosso ad altri nemici." }, { "I forzieri chiusi", "Dopo il combattimento, apri i forzieri della sala: circa 24 Dwarven Heirlooms per Important Heirlooms, e la tavoletta di The Treaty of Understanding." } }
T[5] = { { "Nova di fuoco", "Danni da Fuoco a tutti quelli che gli sono vicino, più volte per combattimento. Per i guaritori: tieni in piena salute chi combatte in mischia." }, { "Montante", "Un colpo violento che respinge il difensore." } }
T[6] = { { "Immolazione", "Brucia un giocatore, poi danni da Fuoco ogni pochi secondi per 21 secondi. Interrompi l'incantesimo o dissolvi la bruciatura." }, { "Maledizione della debolezza", "Riduce i danni fisici di un giocatore per 30 secondi. Un mago o un druido può rimuoverla." } }
T[7] = { { "Fendente", "Colpisce il suo bersaglio e il giocatore più vicino a esso." } }
T[8] = { { "Veleno", "I suoi colpi avvelenano: danni da Natura nel tempo. Cura il veleno se puoi." }, { "Attacco insidioso", "Danni aggiuntivi sul difensore ogni 5-15 secondi." } }
T[9] = { { "I ragni del cortile", "Niente di speciale sul boss stesso. Ripulisci prima gli altri ragni del cortile, altrimenti si uniscono al combattimento." } }
T[10] = { note = "Ripulisci il cortile, clicca sulla statua e tieni duro durante le ondate: arriva dopo.", { "Nova di gelo", "Danni da gelo su tutto il gruppo. Se curi, tieni del mana per tutte le ondate." } }
T[11] = { { "Scagliato in aria", "Scaglia il difensore in aria e lo stordisce per 5 secondi. Attenzione alla minaccia dei danneggiatori: il difensore lo tiene solo per circa metà del combattimento." }, { "Una pattuglia", "Ripulisci la sua sala prima di ingaggiarlo: passa una pattuglia. La sua testa si raccoglie per le missioni Abominable Creatures e Unending Torment." } }
T[12] = { { "Shock di fiamma", "Il suo incantesimo principale. Può essere interrotto e stordito: organizza interruzioni e stordimenti con il gruppo." }, { "Tanti punti salute", "Il combattimento più lungo del dungeon. Continua a interrompere fino alla fine." } }
T[13] = { note = "Ripulisci la casa e la statua, clicca sul camino e tieni duro durante le ondate. Arriva dopo l'ultimo golem di carne.", { "Veleno", "Avvelena il suo bersaglio. Tieni d'occhio le barre della salute." }, { "Colpi potenti", "Picchia forte: tieni in vita il difensore. Prevedi pozioni di mana per le ondate prima di lui." } }
T[14] = { { "Respingimento", "Respinge: ripulisci prima i gruppi intorno a lui, altrimenti atterri in uno di essi." }, { "Scudo anti-magia", "Si protegge per un po' contro gli incantesimi." }, { "Colpi potenti", "Picchia forte: tieni il difensore in piena salute." } }
T[15] = { { "Fulmine", "Resta a distanza per lanciarlo. Interrompilo." }, { "Tocco curativo", "Cura sé stesso o un alleato (lancio di 3 secondi). Interrompilo." }, { "Forma di serpente di Cobrahn", "Al 30% di salute, si trasforma in serpente: colpi più lenti ma più pesanti, e comincia ad addormentare i giocatori." } }
T[16] = { { "Tocco curativo", "Cura sé stessa o un alleato. Interrompila." }, { "Sonno", "Addormenta un giocatore fino a 20 secondi. I danni lo svegliano, e un Dissolvi magia lo rimuove." }, { "Aura di spine", "Danni da Natura a chiunque la colpisca in mischia." } }
T[17] = { { "Guscio scudo", "Per 12 secondi, subisce il 60% di danni in meno e attacca più lentamente ma più forte." } }
T[18] = { { "Tuono", "Danni da Natura a tutti quelli che gli sono vicino, poi attacchi e movimenti rallentati per 10 secondi." }, { "Tocco curativo", "Cura sé stesso o un alleato. Interrompilo." }, { "Sonno", "Addormenta un giocatore fino a 20 secondi." } }
T[19] = { { "Fulmini in serie", "Un fulmine che rimbalza su un secondo giocatore. Interrompilo." } }
T[20] = { { "Tocco curativo", "Una cura lenta (3,5 secondi) su di lui o su un alleato. Interrompilo." }, { "Sonno", "Addormenta un giocatore fino a 20 secondi." }, { "Fulmine", "Resta a distanza per lanciarlo. Interrompilo." } }
T[21] = { { "Rampicanti avidi", "Quando il suo bersaglio è vicino, atterra e immobilizza tutti quelli che gli sono vicino per 10 secondi. Se è a distanza, mantieni le distanze." } }
T[22] = { note = "Uccidi Lady Anacondra, Lord Cobrahn, Lord Pythas e Lord Serpentis, poi parla con il discepolo di Naralex all'ingresso e scortalo fino a Naralex. Proteggilo durante il rituale: Mutanus arriva alla fine.", { "Calpestio del tuono", "Danni da Natura a tutti quelli che gli sono vicino e uno stordimento di 2,5 secondi." }, { "Incubo di Naralex", "Addormenta un giocatore fino a 15 secondi." }, { "Terrorizzare", "Fa fuggire un giocatore in preda al terrore per 4 secondi." } }
T[23] = { { "Colpo di Rhahk'Zor", "Colpisce forte il difensore e lo stordisce per 3 secondi." } }
T[24] = { { "Perforare l'armatura", "Riduce l'armatura del difensore del 75% per 20 secondi." }, { "Fugge a cercare aiuto", "Al 15% di salute, fugge a cercare aiuto. Finiscilo prima che si allontani." } }
T[25] = { note = "Pilota lo Sneed's Shredder e ne esce quando viene distrutto.", { "Disarmare", "Disarma il difensore per 6 secondi." } }
T[26] = { { "Terrorizzare", "Fa fuggire un giocatore in preda al terrore per 4 secondi." }, { "Dolore opprimente", "Rallenta i lanci di un giocatore del 35% per 15 secondi." } }
T[27] = { { "Metallo fuso", "Danni da Fuoco ogni 3 secondi per 15 secondi, con attacchi e movimenti rallentati. Interrompi il lancio di 2 secondi." } }
T[28] = { { "Martellata violenta", "Al 66% e poi al 33% di salute, stordisce tutti quelli intorno a lui, poi va al suo forziere a cambiare armi." }, { "Percuotere", "Con le sue due asce, dal 66% di salute: attacchi aggiuntivi sul difensore." }, { "Potente schiaffo", "Con il suo martello, sotto il 33% di salute: un colpo violento che stordisce il difensore per 3 secondi." } }
T[29] = { { "Arpione avvelenato", "Un lancio di 2 secondi: un colpo, poi danni da Natura per un minuto. Cura il veleno." }, { "Fendente", "Colpisce il suo bersaglio e il giocatore più vicino a esso." } }
T[30] = { { "Percuotere", "Ogni tanto, due attacchi aggiuntivi: grossi colpi sul difensore." }, { "Alleati di VanCleef", "A metà salute, chiama due furfanti Defias." } }
T[31] = { { "Getto d'acido", "Danni da Natura ogni 5 secondi per 30 secondi a tutti quelli che gli sono vicino." }, { "Cucina di Cookie", "Sotto metà salute, si cura (lancio di 2 secondi). Interrompilo." }, { "Fugge a cercare aiuto", "Al 15% di salute, fugge a cercare aiuto. Finiscilo prima che si allontani." } }
T[32] = { { "Risucchio d'anima", "Immobilizza un giocatore per 10 secondi e ne risucchia la salute per curarsi. Interrompi il lancio di 2 secondi o dissolvilo." } }
T[33] = { { "Colpo storto", "Il destriero corrotto stordisce tutti quelli che gli sono vicino per 3 secondi, e subiscono più danni fisici. Il destriero oscuro non ha nessuna tecnica." } }
T[34] = { { "Risucchio del macellaio", "Risucchia 350 punti di mana al suo bersaglio in mischia: un difensore con del mana se ne accorge." } }
T[35] = { { "Velo d'ombra", "Maledice un giocatore: le cure che riceve sono più deboli del 75% per 15 secondi. Rimuovila, soprattutto dal difensore." } }
T[36] = { { "Luce sacra", "Cura sé stesso o un alleato (lancio di 2,5 secondi). Interrompilo." }, { "Scudo divino", "Lo rende immune a tutti i danni e a tutti gli incantesimi per 10 secondi." }, { "Martello della giustizia", "Stordisce un giocatore per 4 secondi." } }
T[37] = { { "Chiama aiuto", "Quando lo ingaggi, chiama le creature entro 30 metri. Ripulisci prima intorno a lui." }, { "Rabbia ululante", "Al 60%, 40% e 20% di salute, i suoi colpi diventano più forti." } }
T[38] = { { "Fendente", "Colpisce il suo bersaglio e il giocatore più vicino a esso." }, { "Spezzaginocchio", "Rallenta i movimenti del suo bersaglio per 10 secondi." } }
T[39] = { note = "Arrivano in quattro dopo la morte di Fenrus il Divoratore: Arugal appare per un istante e li chiama.", { "Offerta oscura", "Cura un altro Camminatore del Vuoto. Uccideteli uno alla volta." } }
T[40] = { { "Bava tossica", "Danni da Natura ogni 6 secondi e mana risucchiato, per 2 minuti. Cura il veleno." } }
T[41] = { { "Worg di rinforzo", "Più il combattimento dura, più worg ha con sé: un worg pallido dopo 30-45 secondi, poi un worg schiumante, poi un orrore lupino." } }
T[42] = { { "Dardo del Vuoto", "Un dardo d'Ombra di 3 secondi sul difensore, ancora e ancora. Interrompilo." }, { "Maledizione di Arugal", "Trasforma un giocatore che non è il difensore in un Shadowfang Glutton che combatte per lui per 10 secondi. Rimuovi la maledizione." }, { "Passo d'ombra", "Si teletrasporta tra il suo cornicione, il cornicione in alto e la scalinata." }, { "Schianto del tuono", "Quando il difensore lo raggiunge: danni da Natura e uno stordimento di 5 secondi intorno a lui." } }
T[43] = { { "Calpestare", "Colpisce tutti quelli che gli stanno vicino." } }
T[44] = { { "Fulmine biforcuto", "Danni da Natura in un cono davanti a lei (lancio di 2 secondi). Stai fuori dal cono." }, { "Nova di gelo", "Congela sul posto tutti quelli che le sono vicino fino a 8 secondi." }, { "Lentezza", "Rallenta i movimenti e gli attacchi di un giocatore per 10 secondi." } }
T[45] = { { "Rete", "Immobilizza un giocatore sul posto per 10 secondi." } }
T[46] = { note = "Clicca sulla Fathom Stone nell'acqua: ne emerge.", { "Dardo di gelo", "Resta a distanza per lanciarlo: danni da Gelo e rallentamento." }, { "Nova di gelo", "Immobilizza tutti quelli che gli sono vicino fino a 8 secondi." } }
T[47] = { { "Sonno", "Addormenta tutti quelli che gli sono vicino fino a 10 secondi. I danni svegliano chi dorme." }, { "Attacco mentale", "Danni da Ombra a un giocatore (lancio di 1,5 secondi)." } }
T[48] = { note = "Aspetta in una grotta sott'acqua, sotto il tempio del Signore del Crepuscolo Kelris, e molti gruppi lo mancano. Nuota sotto il tempio per raggiungerlo." }
T[49] = { note = "Dopo la morte del Signore del Crepuscolo Kelris, accendi uno dopo l'altro i quattro fuochi di Aku'mai nella sua sala. Ognuno porta un'ondata di creature. Quando sono tutte morte, la porta di Aku'mai si apre.", { "Nube velenosa", "Danni da Natura ogni 5 secondi per 45 secondi a tutti quelli vicini." }, { "Rabbia frenetica", "Sotto il 30% di salute: raffiche di attacchi più veloci del 75%, ancora e ancora." } }
T[50] = { { "Scudo di fulmini", "Il fulmine colpisce chiunque lo tocchi. Un sacerdote o uno sciamano può rimuoverlo." }, { "Fulmine", "Resta a distanza per lanciarlo. Interrompilo." } }
T[51] = { { "Colpo di scudo", "Colpisce il difensore e lo stordisce per 2 secondi." }, { "Fugge a cercare aiuto", "Al 15% di salute, fugge a cercare aiuto. Finiscilo prima che si allontani." } }
T[52] = { { "Fugge a cercare aiuto", "Al 15% di salute, fugge a cercare aiuto. Finiscilo prima che si allontani." } }
T[53] = { { "Percuotere", "Ogni tanto, due attacchi aggiuntivi: grossi colpi sul difensore." }, { "Infuriare", "Al 30% di salute, attacca il 30% più veloce fino alla fine del combattimento." } }
T[54] = { { "Catena di fulmini", "Un fulmine che rimbalza da giocatore a giocatore (lancio di 2 secondi). Interrompilo." }, { "Brama di sangue", "Accelera i suoi attacchi o quelli di un alleato del 30% per 30 secondi. Un sacerdote o uno sciamano può rimuoverla." } }
T[55] = { { "Assalto", "Colpisce il bersaglio con il danno dell'arma più 5. Tieni in vita il tank." } }
T[56] = { { "Bomba fumogena", "Stordisce tutti quelli che gli sono vicino per 4 secondi." }, { "Grido di battaglia", "Più potenza d'attacco per lui e i suoi alleati per 2 minuti." }, { "Fugge a cercare aiuto", "Al 15% di salute, fugge a cercare aiuto. Finiscilo prima che si allontani." } }
T[57] = { { "Molti punti ferita", "Niente di speciale visto durante il combattimento: colpisce e ha molta vita. Si aggira nella palude iniziale tra coccodrilli d'élite, quindi ripuliscili prima o attiralo lontano da loro." } }
T[58] = { note = "Uccidi la matriarca dei raptor nell'erba alta. Alla sua morte arriva un'ondata di raptor, e Dente d'Ombra accorre quando sono tutti morti.", { "Raptor nell'erba", "Dei piccoli raptor sbucano dall'erba quando la attraversi e ti fanno sanguinare." }, { "L'ondata prima di lui", "Uccidi tutti i raptor dell'ondata prima che arrivi. Un gruppo è morto al primo tentativo con Dente d'Ombra e diversi raptor addosso nello stesso momento." }, { "Paura", "Il tank viene spaventato più volte durante questo combattimento. Il Totem Tremore di uno sciamano aiuta." } }
T[59] = { { "L'accampamento Gola del Drago", "Si trova in un accampamento Gola del Drago. I suoi gruppi si attirano facilmente uno alla volta: prendili prima uno per volta. Il combattimento in sé è breve, niente di speciale visto finora." } }
T[60] = { note = "Se ne sta immobile in fondo al sentiero dei ragni. Clicca sul piccolo pannello accanto a lui per svegliarlo.", { "Azzeramento della minaccia", "Azzera la sua minaccia e cambia bersaglio durante il combattimento. Danni, rallentate quando il tank lo perde. Tank, riprendilo subito." } }
T[61] = { note = "Si trova vicino a un cerchio rituale nelle fogne, circondato da negromanti del Kirin Tor.", { "Frenesia Empia", "Accelera i suoi attacchi del 75% per 20 secondi. È magia: l'Espiazione di uno sciamano o la Dissolvi Magie di un sacerdote gliela rimuove." }, { "Percossa", "Ogni tanto colpisce due volte in più con un solo colpo, e Colpire aggiunge danni al colpo successivo: il tank incassa colpi pesanti." }, { "Rianimare Morti", "Durante il combattimento degli scheletri si rialzano di continuo attorno al cerchio. Sono deboli: uccidili man mano che arrivano." }, { "Disarmare", "Disarma il tank per circa 6 secondi." } }
T[62] = { note = "Non c'è all'inizio. Nelle fogne, dopo Atrexis, ripulisci la stanza a nordest, quella con le bancarelle del mercato e un piccolo cerchio di evocazione rosa (non il grande cerchio di Atrexis). Un giocatore che ha con sé il Tomo di Dalaran clicca poi sul cerchio, e Lyn esce dal grande portone rotondo con la grata. Per ottenere il tomo, raccogli il Tomo nero sul tavolo della stanza dell'arcimago Arugal, nella Fortezza di Zanna Oscura, dopo aver ucciso Arugal, poi usalo al Leyline Focus, un cristallo blu in una stanza sul retro di Mulino d'Ambra, nella Selva di Argento.", { "Salva di Dardi d'Ombra", "Dardi d'ombra su tutti entro 30 metri da lei." }, { "Maledizione delle Spine", "1,5 secondi di lancio: una maledizione di 3 minuti che ferisce ogni tanto il giocatore quando attacca. Rimuovila." }, { "Scheletri", "Degli scheletri si rialzano e combattono al suo fianco. Uccidili." } }
T[63] = { { "Esplosione Focalizzata", "Dopo 3 secondi di lancio, un raggio parte davanti a lui per 6 secondi e colpisce quattro volte al secondo. Esci dalla sua traiettoria appena inizia il lancio." }, { "Dardo Arcano", "Il suo attacco sul tank tra un raggio e l'altro, lancio di 1,5 secondi." } }
T[64] = { { "Metamorfosi Arcana", "Trasforma un giocatore in un animale per 8 secondi. È magia: dissolvila." }, { "Silenzio", "Silenzia per 10 secondi. Guaritori, tenetevi a distanza." }, { "Arcane Manalings", "Evoca di continuo dei piccoli Arcane Manalings. Uccidili con danni ad area." } }
T[65] = { { "Malfunzionamento", "2 secondi di lancio, poi per 6 secondi l'energia arcana colpisce tutti entro 25 metri ogni 2 secondi, per circa 140 danni a ogni colpo. A distanza, restate oltre i 25 metri; in mischia, uscite durante il lancio." }, { "Angry Tomes", "Degli Angry Tomes ti si lanciano contro lungo il percorso. Uccidili prima di ingaggiare il boss." } }
T[66] = { { "Indebolire", "2 secondi di lancio: un'energia arcana prosciuga fino a 200 punti di mana a tutti entro 45 metri da lui." }, { "Risucchio Vitale", "Un effetto magico sul tank: circa 65 danni Arcani ogni 2 secondi per 10 secondi. Dissolvilo." }, { "La sua stanza", "Le creature ancora vive nella sua stanza si uniscono al combattimento quando lo ingaggi. Ripulisci prima la stanza." } }
T[67] = { note = "Aspetta dietro una barriera magica al centro della città, sorvegliata da Suffused Treants. Uccidi i treant, poi parla con il magus Fansy Goodbringer, subito a sud della barriera: la fa cadere.", { "Legno Vile", "Dei rampicanti sfrecciano verso un giocatore e colpiscono tutti entro 5 metri da lui, poi lasciano vapori tossici al suolo. Esci dai vapori." }, { "Calpestare", "Calpesta i giocatori accanto a lui per circa 100 danni fisici." }, { "Intralciare", "Immobilizza fino a due giocatori vicini a lui per qualche secondo e li ferisce nel tempo. È magia: dissolvetela." } }
T[68] = { note = "L'arcimago Modera apre al gruppo un portale verso la camera purpurea: porta da lui.", { "Mana Rimbalzante", "Una sfera schizza verso un giocatore a caso e poi torna da lui. Tutti quelli che attraversa subiscono danni Arcani e sono silenziati per 6 secondi: non metterti tra lui e quel giocatore." }, { "Metamorfosi di Massa", "Quando finisce il mana, trasforma tutto il gruppo in animali per 8 secondi, poi incanala Evocazione per 6 secondi per riempirlo." }, { "Lentezza", "Rallenta tutti quelli attorno a lui per 3 secondi: attacchi e lanci più lenti del 30%, movimento più lento del 70%." }, { "Restate nella stanza", "Se qualcuno esce dalla stanza durante il combattimento, torna a piena salute." } }
T[69] = { { "Rete", "Immobilizza tutti quelli che gli sono vicino per 10 secondi." }, { "Rallentamento", "Rallenta gli attacchi e i movimenti di un giocatore per 10 secondi e può stordirlo." }, { "Evocazione di uno scarafaggio meccanico", "Chiama degli scarafaggi meccanici. Il suo Aggiornamento li uccide e lo cura." } }
T[70] = { note = "Parla con l'artificiere Emi Shortfuse e proteggila mentre fa saltare le due entrate delle grotte. I trogg arrivano a ondate, poi Grubbis arriva con Chomper." }
T[71] = { { "Megavolt", "Danni da Natura in un cono davanti a lui (lancio di 2 secondi). Solo il difensore si mette davanti." }, { "Catena di fulmini", "Un fulmine che rimbalza sui giocatori vicini (lancio di 2,5 secondi). Interrompilo." } }
T[72] = { { "Falciare la folla", "Colpisce tutti quelli che gli sono vicino e interrompe i loro incantesimi. Incantatori e guaritori, state a distanza." }, { "Colpo ad arco", "Colpisce tutti in un cono davanti a lui." }, { "Calpestare", "Colpisce tutti quelli che gli stanno vicino." } }
T[73] = { { "Evocazione di un servitore infuocato", "Chiama due servitori infuocati all'inizio del combattimento." }, { "Palla di fuoco", "Resta a distanza per lanciarla. Interrompilo." }, { "Scudo di fuoco II", "Danni da Fuoco a tutti quelli che gli sono vicino per un minuto. Un sacerdote o uno sciamano può rimuoverlo." } }
T[74] = { { "Bombe ambulanti", "Accende una a una le teste di gnomo intorno alla sala, e ognuna sgancia bombe ambulanti che esplodono quando raggiungono un giocatore. Il pulsante accanto a una testa la spegne. Sotto metà salute le accende più in fretta." }, { "Respingere", "Respinge il difensore. Sotto metà salute colpisce tutti quelli intorno a lui." } }
T[75] = { { "Evocazione Spirito del Cinghiale", "Chiama uno Spirito del Cinghiale al suo fianco ogni 30-45 secondi (lancio di 1,5 secondi). Uccidi ognuno prima che arrivi il successivo." }, { "Salva Curativa", "Sotto il 75% di vita si cura, e la cura rimbalza su due alleati vicini (lancio di 2,5 secondi). Interrompilo." } }
T[76] = { { "Dominare la Mente", "Prende il controllo di un giocatore che non è il suo bersaglio per 15 secondi (lancio di 2 secondi). Interrompilo, o dissolvi l'effetto sul giocatore." }, { "Dardo d'Ombra", "Resta a distanza per lanciarlo. Interrompilo." } }
T[77] = { { "Chiama aiuto", "Quando lo ingaggi, chiama le creature entro 15 metri, compresi i due Lanciatori Vilspine al suo fianco. Tieni sotto controllo uno dei due durante il combattimento." }, { "Tuono", "Ogni 8-14 secondi: danni da Natura a tutti quelli vicini a lui, e i loro attacchi e movimenti sono rallentati per 10 secondi." } }
T[78] = { { "Carica Turbinante", "Colpisce tutti quelli che gli stanno vicino." }, { "Aura di Spine", "Chiunque colpisca lui o un alleato vicino (compreso Overlord Ramtusk) subisce danni da Natura." } }
T[79] = { note = "Una protezione chiude la sua grotta. Uccidi i due Guardiani Teschio Morto davanti: cade quando entrambi sono morti.", { "Lasciato per Morto", "Ogni 21-35 secondi colpisce un giocatore che non è il suo bersaglio, che cade come morto e non può più attaccare né lanciare incantesimi. Muoversi vi pone fine." }, { "Devastare", "Ogni 25-31 secondi: colpisce tutti quelli vicino a lui e li stordisce per 2,5 secondi." }, { "Arrabbiarsi", "A 60% di vita, poi a 40%, attacca il 60% più veloce e colpisce più forte per 2 minuti." } }
T[80] = { note = "Un pipistrello raro: non c'è a ogni passaggio. Quando c'è, aspetta in un piccolo incavo della parete della grotta dei pipistrelli, vicino a Charlga Razorflank." }
T[81] = { { "Catena di Fulmini", "Resta a distanza e la lancia ripetutamente: un fulmine che rimbalza su un massimo di 3 giocatori (lancio di 2,5 secondi). Interrompilo." }, { "Purezza", "Ogni 9-15 secondi è immune a tutti gli attacchi e a tutti gli incantesimi per 2 secondi." }, { "Rinnovamento", "Cura un alleato ferito, o se stessa, nell'arco di 15 secondi. Un sacerdote o uno sciamano può rimuoverlo." } }
T[82] = { { "Evocazione Brontolatore della Terra", "Un Brontolatore di Pietra lo accompagna e combatte al suo fianco." }, { "Fulmine", "Resta a distanza per lanciarlo. Interrompilo." }, { "Fugge a cercare aiuto", "A 15% di vita fugge a cercare aiuto. Finiscilo prima che si allontani." } }
T[83] = { { "Evocazione Brontolatore della Terra", "Un Brontolatore di Pietra lo accompagna e combatte al suo fianco." }, { "Fulmine", "Resta a distanza per lanciarlo. Interrompilo." } }
T[84] = { { "Parola dell'Ombra: Dolore", "Danni d'ombra al suo bersaglio ogni 3 secondi per 18 secondi. Un Dissolvi Magie lo rimuove." } }
T[85] = { note = "Circa una partita su tre, uno dei tre rari del cimitero si trova in uno dei sei punti della mappa: Azshir the Sleepless, Fallen Champion o Ironspine.", { "Richiamo della Tomba", "Dopo 60 secondi, danni d'ombra al giocatore (lancio di 2 secondi). Un mago o un druido può rimuoverlo prima." }, { "Terrorizzare", "Fa fuggire un giocatore in preda alla paura per 4 secondi." }, { "Risucchio d'Anima", "Sotto metà vita prosciuga un giocatore e il giocatore più vicino a lui per 12 secondi, e si cura." } }
T[86] = { note = "Circa una partita su tre, uno dei tre rari del cimitero si trova in uno dei sei punti della mappa: Azshir the Sleepless, Fallen Champion o Ironspine.", { "Fendente", "Colpisce il suo bersaglio e il giocatore più vicino a esso." }, { "Esecuzione", "Colpisce forte un bersaglio al 20% di vita o meno. Tieni il tank sopra quella soglia." } }
T[87] = { note = "Circa una partita su tre, uno dei tre rari del cimitero si trova in uno dei sei punti della mappa: Azshir the Sleepless, Fallen Champion o Ironspine.", { "Maledizione della Debolezza", "Riduce i danni fisici di tutti entro 30 metri per 2 minuti. Un mago o un druido può rimuoverla." }, { "Nube Velenosa", "Danni da Natura ogni 5 secondi per 45 secondi a tutti i vicini." } }
T[88] = { { "Dardi di Fiamma", "Una colonna di fiamme dove si trova un giocatore (lancio di 3 secondi): danni da Fuoco, poi ancora ogni 3 secondi per 9 secondi. Spostati." }, { "Nova di Fuoco", "Danni da Fuoco a tutti entro 10 metri da lui." }, { "Folgore di Fiamma", "Danni da Fuoco a un giocatore, poi ancora ogni 3 secondi per 12 secondi. Un Dissolvi Magie lo rimuove." }, { "Dardo d'Ombra", "Resta a distanza per lanciarlo. Interrompilo." } }
T[89] = { { "Cani da Caccia Scarlatti", "Tre cani lo accompagnano e attaccano con lui, e dà loro anche Sete di Sangue. Uccidili per primi." }, { "Sete di Sangue", "Accelera i suoi attacchi o quelli di un alleato del 30% per 30 secondi. Un sacerdote o uno sciamano può rimuoverla." }, { "Grido di Battaglia", "Più potenza d'attacco per lui e i suoi cani per 3 minuti." } }
T[90] = { { "Detonazione", "A metà vita si chiude per 8 secondi in una Bolla Arcana e lancia Detonazione (lancio di 5 secondi): pesanti danni da Fuoco a tutti entro 30 metri. Esci dalla portata prima dell'esplosione, poi torna." }, { "Metamorfosi", "Trasforma in pecora un giocatore che non è il suo bersaglio per un massimo di 20 secondi (lancio di 1,5 secondi). Interrompilo, o dissolvi l'effetto sul giocatore." }, { "Silenzio", "Silenzia tutti entro 15 metri per 10 secondi (lancio di 1,5 secondi). Se curi, resta più lontano." }, { "Esplosione Arcana", "Ogni pochi secondi, danni Arcani a tutti entro 10 metri. A distanza, mantieni le distanze." } }
T[91] = { { "Turbine", "Ogni 15-25 secondi gira su se stesso per 10 secondi e colpisce tutti quelli vicino a lui. In mischia, allontanati fino alla fine." }, { "Fendente", "Colpisce il suo bersaglio e il giocatore più vicino a esso." }, { "Arrabbiarsi", "A 30% di vita attacca il 60% più veloce e colpisce più forte per 2 minuti." }, { "Giovani Reclute Scarlatte", "Alla sua morte, 20 Giovani Reclute Scarlatte entrano dalla porta della stanza e attaccano. Resta con il tuo gruppo e usa danni ad area." } }
T[92] = { { "Maledizione di Tuten'kash", "Maledizione che riduce del 15% la velocità di lancio e rallenta del 18% gli attacchi dei giocatori vicini per 15 min. Rimuovi la maledizione." } }
T[93] = { { "Palla di Fuoco", "Una palla di fuoco sul bersaglio, di continuo. Interrompilo." }, { "Esplosione di Fuoco", "Danni da Fuoco a tutti i giocatori vicini a lui. Allontanati quando lo lancia." } }
T[94] = { { "Nube di Malattia", "Una nube di malattia intorno a lui ferisce i vicini ogni 3 secondi. Combatti a distanza o cura la malattia." }, { "Frenesia", "Si infuria e aumenta danni e velocità d'attacco per 2 minuti. Cura di più il tank." } }
T[95] = { { "Dominio Mentale", "Controlla un giocatore per 10 secondi. Dissipa l'effetto ed evita che danneggi il gruppo." }, { "Parola d'Ombra: Dolore", "Danni da Ombra ogni 3 secondi per 18 secondi. Dissipalo." }, { "Cura", "Cura se stesso o un alleato. Interrompi l'incantesimo." }, { "Dardo d'Ombra", "Un dardo di danni da Ombra su un bersaglio, 3 s di lancio. Interrompilo." } }
T[96] = { { "Ira di Amnennar", "Respinge un bersaglio. Torna in posizione." }, { "Dardo di Gelo", "Un dardo di gelo che rallenta il bersaglio, lanciato di continuo. Interrompilo." }, { "Esplosione Gelida", "Danni da Gelo e immobilizzazione di tutti i vicini. Dissipa l'immobilizzazione." } }
T[97] = { { "Tocco Indebolente", "Malattia che infligge danni da Ombra e risucchia mana ogni 10 sec per 3 min, trasferendolo a lui. Curala, soprattutto sugli incantatori." }, { "Lezzo Putrido", "Riduce di 50 Forza e Agilità dei giocatori vicini per 10 sec e impedisce loro di lanciare incantesimi. Incantatori, state lontani da lui." } }
T[98] = { note = "Si trova a terra nella piccola stanza accanto all'altare, come morto, e si rialza quando viene attaccato.", { "Paura", "Fa fuggire un giocatore terrorizzato fino a 8 secondi (lancio di 1,5 secondi). Interrompilo." }, { "Sonno", "Addormenta tutti quelli vicino a lui fino a 10 secondi. I danni svegliano chi dorme." }, { "Maledizione del Sangue", "Un giocatore subisce più danni fisici per 10 minuti (lancio di 2 secondi). Un mago o un druido può rimuoverla." }, { "Cura", "A 30% di vita si cura (lancio di 3 secondi). Interrompilo." } }
T[99] = { { "Chiama aiuto", "Quando lo ingaggi, chiama tutti i difensori Scarlatti entro 80 metri. Ripulisci la cattedrale prima di ingaggiarlo." }, { "Martello della Giustizia", "Stordisce un giocatore per 5 secondi." }, { "Scudo Divino", "A metà vita diventa immune a tutti i danni e a tutti gli incantesimi per 12 secondi." }, { "Aura di Retribuzione", "Danni Sacri a chiunque lo colpisca in mischia." } }
T[100] = { note = "Quando Mograine cade, finge solo di essere morto: lei esce dalla stanza dietro l'altare e attacca.", { "Resurrezione Scarlatta", "A metà vita addormenta l'intera stanza fino a 10 secondi, corre da Mograine e lo resuscita. Lui le restituisce tutta la vita con Imposizione delle Mani, e i due combattono insieme contro di te." }, { "Punizione", "Danni Sacri al suo bersaglio (lancio di 2,5 secondi). Interrompila." }, { "Cura", "Cura l'alleato più ferito, compreso Mograine (lancio di 3 secondi). Interrompila." }, { "Parola del Potere: Scudo", "La protegge dai danni fino a 30 secondi. Un sacerdote o uno sciamano può rimuoverlo." } }
T[101] = { { "Carica Scattante", "Aumenta la sua velocità di movimento per 3 sec e aggiunge danni al suo primo attacco. Cura chi viene colpito." } }
T[102] = { { "Assalto", "Un colpo in mischia con danni aumentati sul bersaglio. Cura il tank." } }
T[103] = { { "Colpo di Scudo", "Colpisce il bersaglio e lo stordisce per 2 secondi. Cura durante lo stordimento." } }
T[104] = { { "Dardo Fulminante", "Un dardo di Natura sul bersaglio. Interrompilo." }, { "Catena di Fulmini", "Fulmine della Natura che rimbalza fino a 3 giocatori. Interrompilo e sparpagliatevi." } }
T[105] = { { "Frantumazione Arcuata", "Un colpo ad arco su tutti quelli davanti a lei. Resta fuori dal suo fronte." }, { "Allontanamento", "Infligge danni extra al bersaglio e lo respinge. Cura il tank." }, { "Urto di Guerra", "Respinge e stordisce tutti i vicini per 5 secondi. Cura durante lo stordimento." } }
T[106] = { { "Tempeste delle Sabbie", "Evoca una tempesta di sabbia che combatte per lui per 30 secondi. Uccidila o allontanati." }, { "Tempeste delle Sabbie", "Evoca una tempesta di sabbia che combatte per lui per 30 secondi. Uccidila o allontanati." } }
T[107] = { { "Sferzata Fiammeggiante", "Danni da Fuoco che riducono la resistenza al Fuoco del bersaglio per 45 secondi. Cura il tank." }, { "Amplifica Fiamme", "Aumenta di 100 i danni da Fuoco subiti dal bersaglio per 30 secondi. Cura di più il tank." }, { "Esplosione di Fuoco", "Danni da Fuoco a tutti i giocatori vicini a lui. Allontanati quando lo lancia." } }
T[108] = { { "Brama di Sangue", "Aumenta del 30% la velocità di attacco di un alleato per 30 secondi. Aspettati colpi più rapidi sul tank." }, { "Catena di Dardi", "Un fulmine che rimbalza fino a 3 giocatori. Interrompilo e sparpagliatevi." }, { "Dardo Fulminante", "Un fulmine di Natura sul bersaglio. Interrompilo." }, { "Riduzione", "Riduce di 1 Forza e Costituzione dei giocatori vicini per 2 minuti. L'effetto è minore." } }
T[109] = { { "Tremore Terrestre", "Stordisce tutti i giocatori vicini a lui. Cura durante lo stordimento." }, { "Frenesia", "Aumenta del 60% la sua velocità di attacco e di 50 i suoi danni fisici per 2 minuti. Cura di più il tank." }, { "Risveglio Guardiano Terrigeno", "Risveglia Guardiani di Terra che attaccano il gruppo. Uccidili o tienili lontani dal guaritore." }, { "Risveglio Custode della Volta", "Risveglia Guardiani della Camera che si uniscono allo scontro. Gestisci i nemici extra prima che sopraffacciano il gruppo." } }
T[110] = { { "Totem della Presa della Terra", "Evoca per 30 secondi un totem che immobilizza periodicamente i giocatori vicini. Distruggi il totem o resta fuori dal suo raggio." }, { "Ondata di Cura di Antu'sul", "Cura il bersaglio per 2247-2608. Interrompilo." }, { "Guardia Curativa", "Evoca per 30 secondi una guardia che cura periodicamente gli alleati intorno a sé. Distruggila in fretta." } }
T[111] = { { "Piaga Febbrile", "Un dardo di Natura di 4,5 secondi seguito da danno da Natura per 3 minuti. Interrompilo o cura la malattia." } }
T[112] = { { "Assalto", "Un colpo in mischia con danni aumentati sul bersaglio. Cura il tank." } }
T[113] = { { "Guardiano di Zum'rah", "Lancia un totem per 20 secondi che evoca periodicamente uno scheletro, ciascuno della durata di 20 secondi. Distruggi prima il totem." }, { "Ondata di Cura", "Cura un alleato con la magia della Natura. Interrompilo." }, { "Dardo d'Ombra", "Un dardo d'Ombra sul bersaglio. Interrompilo." }, { "Raffica di Dardi d'Ombra", "Danni da Ombra a tutti i giocatori vicini. Interrompilo." } }
T[114] = { { "Piaga Febbrile", "Un dardo di Natura di 4,5 secondi seguito da danno da Natura per 3 minuti. Interrompilo o cura la malattia." } }
T[115] = { { "Rinnovamento", "Cura un alleato di 5 ogni 3 secondi per 20 secondi. Interrompilo." }, { "Cura", "Cura un alleato con la magia del Sacro. Interrompilo." }, { "Urlo Psichico", "Spaventa fino a 5 giocatori vicini per 6 secondi. Usa una protezione dalla paura o stai a distanza." }, { "Dardo d'Ombra", "Un dardo d'Ombra sul bersaglio. Interrompilo." } }
T[116] = { { "Veleno Virulento", "Avvelena il bersaglio. Cura il veleno o cura il danno." } }
T[117] = { { "Esecuzione", "Finisce un giocatore con il 20% di salute o meno con danni extra. Resta sopra il 20% di salute." }, { "Fendente", "Colpisce un bersaglio e il suo alleato più vicino con danni da arma. Non stare vicino al tank." } }
T[118] = { { "Blocco Migliorato", "Aumenta dell'85% la sua probabilità di parare per 6 secondi. Molti tuoi colpi verranno parati per un po'." }, { "Sfondamento di Scudo", "Interrompe gli incantesimi di un giocatore. Incantatori, non iniziate incantesimi lunghi su di lui." }, { "Rivincita", "Contrattacca il bersaglio per 16-20 danni dopo un blocco, una schivata o una parata. Cura il tank." } }
T[119] = { { "Stalattite Ghiacciata", "Dardo di gelo con 1,5 s di lancio che rallenta il movimento del 50% per 10 s. Interrompilo." }, { "Congelamento Solido", "Lancio di 2,5 s che stordisce un giocatore e infligge danni da Gelo ogni 3 s per 10 s. Interrompilo e cura il bersaglio." }, { "Contusione di Gahz'rilla", "Colpisce i giocatori vicini e li respinge. Resta fuori dalla portata di mischia se puoi." } }
T[120] = { { "Frenesia", "Aumenta la sua velocità d'attacco e i danni fisici per 2 minuti. Un Colpo Tranquillante o simile aiuta; altrimenti difese del tank e cure." }, { "Fendente Ampio", "Colpisce tutti in un cono davanti a lui. Resta fuori dal cono, tranne il tank." }, { "Fendente", "Colpisce un bersaglio e il suo alleato più vicino con danni da arma. Non stare vicino al tank." } }
T[121] = { { "Rete", "Immobilizza un giocatore entro 20 m per 10 s. Proteggi e cura il giocatore immobilizzato." }, { "Tiro Gelido", "Attacco di Gelo a distanza che rallenta il movimento del 60% per 10 secondi. Avvicinati o eliminalo in fretta." } }
T[122] = { { "Raffica Tossica", "Danni da Natura a un bersaglio a distanza. Cura il bersaglio." } }
T[123] = { { "Fendente", "Colpisce il bersaglio e i suoi alleati più vicini, fino a 3 bersagli. Non stare accanto al tank." }, { "Perforazione", "Danni fisici nel tempo sul tank, ogni 2 secondi per 10 secondi. Cura il tank." } }
T[124] = { { "Bomba Fumogena", "Una nube di fumo che stordisce tutti i vicini per 4 secondi. Cura e mantieni vivo il tank." }, { "Tiro Multiplo", "Colpisce fino a cinque bersagli insieme. Sparpagliatevi per colpire meno giocatori." } }
T[125] = { { "Assalto", "Un forte colpo in mischia sul tank. Mantieni il tank curato." }, { "Urto di Guerra", "Colpisce tutti i vicini, li scaraventa indietro e li stordisce per 8 sec. Cura durante lo stordimento." } }
T[126] = { { "Radici Avvolgenti", "Immobilizza un bersaglio fino a 10 sec, con danni da Natura ogni 3 sec. Interrompilo o dissolvi l'effetto." }, { "Ira Silvana", "Un fulmine di danni da Natura su un bersaglio, 2 s di lancio. Interrompilo." }, { "Forze Corrotte della Natura", "Evoca tre Forze della Natura corrotte che combattono per lui per 1 minuto. Uccidile in fretta o tienile lontane dal gruppo." } }
T[127] = { { "Calpestamento", "Infligge danni extra ai nemici vicini. Stai lontano dal tank." }, { "Allontanamento", "Colpisce il tank e lo respinge. Riportalo in posizione." }, { "Valanga", "Stordisce tutti i vicini per 8 secondi mentre compaiono frammenti ogni 2 secondi. Uccidili in fretta." } }
T[128] = { { "Bomba", "Lancia esplosivi su un'area bersaglio infliggendo danni da Fuoco. Esci dall'area d'impatto." }, { "Archibugio del Drago dei Goblin", "Un cono di fuoco canalizzato per 8 secondi che può esplodere. Resta fuori dal cono." }, { "Bomba Sfollabestie", "Costringe tutte le bestie nel raggio di 5 m a fuggire per 10 sec. Cacciatore, aspettati che il tuo animale scappi." } }
T[129] = { { "Perforazione", "Danni fisici nel tempo sul tank, ogni 2 secondi per 10 secondi. Cura il tank." }, { "Morso Fatale", "Risucchia 100 salute al bersaglio e lo cura fino al doppio di quella quantità. Tieni in vita il tank." } }
T[130] = { { "Falciata", "Le dà due attacchi extra. Aspettati picchi di danni e tieni in vita il tank." }, { "Macigno", "Lancia un masso contro un bersaglio. Cura il bersaglio." }, { "Campo di Polvere", "Scuote il terreno, danneggiando e respingendo i nemici vicini. Mantieni le distanze se puoi." }, { "Atterramento", "Atterra un bersaglio e lo stordisce per 2 sec. Cura durante lo stordimento." } }
