T[132] = { { "Acido di Hakkar", "Danni da Natura nel tempo su un giocatore, ogni 2 secondi per 1 minuto. Tieni pronto il curatore." } }
T[133] = { { "Totem della Presa della Terra", "Evoca per 30 secondi un totem che immobilizza periodicamente i giocatori vicini. Distruggi il totem o resta fuori dal suo raggio." }, { "Colonna di Fuoco", "Evoca un pilastro di fuoco su un'area che brucia chiunque vi si trovi e infligge danni aggiuntivi ogni 2 secondi per 8 secondi. Interrompilo o esci dal fuoco." }, { "Ondata di Cura", "Cura un alleato con la magia della Natura. Interrompilo." } }
