T[136] = { { "Battito Alato", "Respinge tutti quelli di fronte a lui. Resta fuori dal fronte." }, { "Soffio Acido", "Danni da Natura e danni aggiuntivi ogni 5 secondi per 45 secondi a chiunque si trovi in un cono davanti a sé. Resta fuori dalla parte frontale e cura i danni." } }
T[137] = { { "Battito Alato", "Respinge tutti quelli di fronte a lui. Resta fuori dal fronte." }, { "Soffio Acido", "Danni da Natura e danni aggiuntivi ogni 5 secondi per 45 secondi a chiunque si trovi in un cono davanti a sé. Resta fuori dalla parte frontale e cura i danni." } }
