T[139] = { { "Falciata", "Gli conferisce 2 attacchi extra. Cura il tank." }, { "Urto di Guerra", "Respinge e stordisce tutti i vicini per 5 secondi. Cura durante lo stordimento." }, { "Sopore Profondo", "Fa cadere un bersaglio in un sonno profondo per 15 secondi: non può agire. Coprilo finché non si sveglia." }, { "Soffio Acido", "Danni da Natura e danni aggiuntivi ogni 5 secondi per 45 secondi a chiunque si trovi in un cono davanti a sé. Resta fuori dalla parte frontale e cura i danni." } }
